/* ============================================================
   catalog.js - program katalogu

   VERI KAYNAGI
   ------------
   Bu dosya ELLE YAZILMAMISTIR. huneducation.com uzerindeki gercek
   `course` ve `university` kayitlarindan uretilmistir:
       python tools/build_catalog.py canli.json site/assets/data/catalog.js

   Onceki surumde 46 kayit elle derlenmisti ve ucretlerin bir kismi
   canlidaki gercek rakamlarla ortusmuyordu. Simdi 490 kurs ve 20
   universite oldugu gibi aktariliyor.

   UCRET SEMANTIGI
   ---------------
   course_price YILLIKTIR. Canli kurs sayfasi bunu acikca yaziyor:
   "Price: 19 900 usd/year (2 semesters)". Donem sayisi programin
   TOPLAM uzunlugudur (12 donem = 6 yil), yillik ucretin bolen degil.
   Ucretlerin bir kismi USD cinsindendir; para birimi her kayitta durur.
   ============================================================ */

import { LANG, t, money, years, perYear } from '../js/core/i18n.js';

const L = (en, tr) => (LANG === 'tr' ? tr : en);

/* ------------------------------------------------------------
   Canlıdaki program ve üniversite sayfalarına köprü.

   Kayıtlardaki pen/ptr (program) ve sen/str (üniversite) alanları
   canlı slug'lardır; eşleştirme tools/katalog_baglanti.py ile bir kez
   yapıldı. Türkçe karşılığı olmayan 29 programda TR bağlantısı yoktur:
   kart o dilde üniversite sayfasına düşer. Yanlış dile link vermektense
   link vermemek yeğdir.
   ------------------------------------------------------------ */
const KOK = LANG === 'tr' ? 'https://tr.huneducation.com' : 'https://huneducation.com';

export function programUrl(p) {
  const s = LANG === 'tr' ? p.ptr : p.pen;
  return s ? `${KOK}/course/${s}/` : null;
}

export function universiteUrl(u) {
  const s = u && (LANG === 'tr' ? u.str : u.sen);
  return s ? `${KOK}/university/${s}/` : null;
}

